class GridWorld:
    def __init__(self, size=10, goal=9, max_steps=50):
        self.size, self.goal, self.max_steps = size, goal, max_steps

    def reset(self):
        self.pos, self.steps = 0, 0
        return self.pos, {}

    def step(self, action):  # 0 = left, 1 = right
        self.pos = max(0, min(self.size - 1, self.pos + (1 if action == 1 else -1)))
        self.steps += 1
        terminated = self.pos == self.goal
        truncated = self.steps >= self.max_steps
        reward = 1.0 if terminated else -0.01
        return self.pos, reward, terminated, truncated, {}
